  missing_ads JSONB;
  next_payload TEXT;
  now_ms BIGINT := (EXTRACT(EPOCH FROM clock_timestamp()) * 1000)::bigint;
BEGIN
  SELECT payload, revision
    INTO current_payload, current_revision
    FROM warehouse_state
    WHERE id = 1
    FOR UPDATE;

  IF current_payload IS NULL THEN
    RAISE EXCEPTION 'warehouse_state is empty; refusing Kaspi ads import';
  END IF;

  current_json := COALESCE(NULLIF(current_payload, ''), '{}')::jsonb;
  existing_ads := CASE
    WHEN jsonb_typeof(current_json->'kaspiAdExpenses') = 'array'
      THEN current_json->'kaspiAdExpenses'
    ELSE '[]'::jsonb
  END;

  SELECT COALESCE(jsonb_agg(seed.item), '[]'::jsonb)
    INTO missing_ads
    FROM jsonb_array_elements(seed_ads) AS seed(item)
    WHERE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(existing_ads) AS present(item)
        WHERE (
          COALESCE(present.item->>'detailHash', '') <> ''
          AND present.item->>'detailHash' = seed.item->>'detailHash'
        ) OR (
          present.item->>'sourceKey' = seed.item->>'sourceKey'
          AND present.item->>'fromDate' = seed.item->>'fromDate'
          AND present.item->>'toDate' = seed.item->>'toDate'
          AND ABS(COALESCE((present.item->>'amount')::numeric, 0)
              - COALESCE((seed.item->>'amount')::numeric, 0)) < 0.01
        )
    );

  IF jsonb_array_length(missing_ads) = 0 THEN
    RAISE NOTICE 'Kaspi ads 2026-08-10..2026-08-16 already present; no changes';
    RETURN;
  END IF;

  INSERT INTO warehouse_backups(label, payload, revision, created_at)
  VALUES('before-kaspi-ads-2026-08-10--2026-08-16', current_payload, current_revision, now_ms);

  next_payload := jsonb_set(
    current_json,
    '{kaspiAdExpenses}',
    existing_ads || missing_ads,
    true
  )::text;

  UPDATE warehouse_state
    SET payload = next_payload,
        revision = current_revision + 1,
        updated_at = now_ms
    WHERE id = 1;

  RAISE NOTICE 'Imported % Kaspi ad batches; backup created at revision %',
    jsonb_array_length(missing_ads), current_revision;
END
$kaspi_ads$;

